import Search from "antd/es/input/Search";


const SearchContent = () => {
  const onSearch = (value) => console.log(value);

  return (
    <>
      <Search
        placeholder="input search text"
        allowClear
        onSearch={onSearch}
        className="searcContent"
      />
    </>
  )
}

export default SearchContent;
